/**
 * @summary Get a personalized AI coach message
 */
export const getGetCoachMessageUrl = (userId: number) => {
  return `/api/coach/message/${userId}`;
};

export const getCoachMessage = async (
  userId: number,
  options?: RequestInit,
): Promise<CoachMessage> => {
  return customFetch<CoachMessage>(getGetCoachMessageUrl(userId), {
    ...options,
    method: "GET",
  });
};

export const getGetCoachMessageQueryKey = (userId: number) => {
  return [`/api/coach/message/${userId}`] as const;
};

export const getGetCoachMessageQueryOptions = <
  TData = Awaited<ReturnType<typeof getCoachMessage>>,
  TError = ErrorType<unknown>,
>(
  userId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getCoachMessage>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetCoachMessageQueryKey(userId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getCoachMessage>>> = ({
    signal,
  }) => getCoachMessage(userId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!userId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getCoachMessage>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetCoachMessageQueryResult = NonNullable<
  Awaited<ReturnType<typeof getCoachMessage>>
>;
export type GetCoachMessageQueryError = ErrorType<unknown>;

/**
 * @summary Get a personalized AI coach message
 */

export function useGetCoachMessage<
  TData = Awaited<ReturnType<typeof getCoachMessage>>,
  TError = ErrorType<unknown>,
>(
  userId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getCoachMessage>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetCoachMessageQueryOptions(userId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
